        if (baseUrl.includes("url=")) {
            let urlMatch = baseUrl.match(/url=([^&]*)/);
            if (urlMatch) finalUrl = java.base64Decode(urlMatch[1]);
        } else if (baseUrl.startsWith("data:")) {
            let data = JSON.parse(java.base64Decode(baseUrl.split(",")[1]));
            finalUrl = java.base64Decode(data.url);
        }
        let idMatch = finalUrl.match(regex);
        return idMatch ? idMatch[1] : null;
    } catch (e) {
        return null;
    }
}

