function buildChapterUrl(x, catalog, device) {
    let { java } = this;
    const isFanqieApp = ['番茄小说', '番茄短剧', '番茄听书', '番茄畅听'].includes(catalog.source);
    const urlToMatch = x.url || catalog.url;
    const bookId = urlToMatch?.match(/book_id=(\d{19})\b/)?.[1] || null;
    const itemId = urlToMatch?.match(/item_id=(\d+)/)?.[1] || null;

    let chapterParams = {
        cid: x.cid,
        source: catalog.source
    };

    if (catalog.source === '书旗听书') {
        const bookIdMatch = x.url?.match(/[?&]?bookid=(\d+)/);
        const itemIdMatch = x.url?.match(/[?&]?item_ids=(\d+)/);
        if (bookIdMatch && itemIdMatch) {
            chapterParams.bookid = bookIdMatch[1];
            chapterParams.item_ids = itemIdMatch[1];
        }
    }

    if (!isFanqieApp) {
        chapterParams.url = catalog.url;
    } else {
        chapterParams.book_id = bookId;
        chapterParams.item_id = itemId;
    }

    if (['企鹅看书', 'QQ阅读', '起点'].includes(catalog.source) && x.url && typeof x.url == 'string') {
        const bMatch = x.url.match(/bookid=(\d+)/);
        const cMatch = x.url.match(/chapterid=(\d+)/);
        if (bMatch && cMatch) {
            let bid = bMatch[1];
            if (catalog.source == '企鹅看书') {
                bid = bid.length > 2 ? bid.substring(2) : bid;
            }
            chapterParams.bookid = bid;
            chapterParams.chapterid = cMatch[1];
        }
    }

    if (catalog.source == '晋江' || catalog.source == '半夏') {
        const novelIdMatch = x.url?.match(/novelId=(\d+)/);
        const chapterIdMatch = x.url?.match(/chapterId=(\d+)/);
        if (novelIdMatch && chapterIdMatch) {
            chapterParams.novelId = novelIdMatch[1];
            chapterParams.chapterId = chapterIdMatch[1];
        }
    }

    if (catalog.source == '七猫') {
        chapterParams.qm_url = x.url;
    }

    if (catalog.source == '七猫短剧') {
        try {
            let decodedUrl = java.base64Decode(catalog.url);
            let qmIdMatch = decodedUrl.match(/qm_id=(\d+)/);
            if (qmIdMatch) {
                chapterParams.qm_id = qmIdMatch[1];
            }
        } catch (e) {}
    }

    let commentPart = '{"type":"susan"}';

    if (catalog.source == '七猫') {
        const qmBookId = x.url?.match(/book_id=(\d+)/)?.[1] || null;
        const qmChapterId = x.url?.match(/item_id=(\d+)/)?.[1] || null;
        if (qmBookId && qmChapterId) {
            const qmCommentUrl = `${getServerHost.call(this)}/qm_comment?book_id=${qmBookId}&item_id=${qmChapterId}`;
            commentPart = `{"type":"susan","js":"book ? result : '${qmCommentUrl}'"}`;
        }
    } else if (catalog.source == '晋江' || catalog.source == '半夏') {
        const novelId = chapterParams.novelId;
        const chapterId = chapterParams.chapterId;
        if (novelId && chapterId) {
            let jjCommentUrl = `${getServerHost.call(this)}/jj_comment?bid=${novelId}&cid=${chapterId}`;
            if (catalog.source == '半夏') {
                const bjBidMatch = x.url?.match(/bookid=(\d+)/);
                const bjCidMatch = x.url?.match(/chapterid=(\d+)/);
                if (bjBidMatch && bjCidMatch) {
                    jjCommentUrl += `&bookid=${bjBidMatch[1]}&chapterid=${bjCidMatch[1]}`;
                }
            }
            commentPart = `{"type":"susan","js":"book ? result : '${jjCommentUrl}'"}`;
        }
    } else if (catalog.source == '番茄小说') {
        const fanqieCommentUrl = `${getServerHost.call(this)}/comment?sessionid=${getSessionId.call(this)}&item_id=${itemId}&book_id=${bookId}`;
        commentPart = `{"type":"susan","js":"book ? result : '${fanqieCommentUrl}'"}`;
    } else if (catalog.source == '云端') {
        const decodedUrl = java.base64Decode(catalog.url);
        const commentUrl = decodedUrl.replace('pt=web', 'pt=3g');
        commentPart = `{"type":"susan","js":"book ? result : '${commentUrl}'"}`;
    }

    let encodedParams = java.base64Encode(JSON.stringify(chapterParams));
    return `data:chapterUrl;base64,${encodedParams},${commentPart}`;
}

