  color: #2196F3;
}

.toast-icon.loading {
  background: rgba(45, 157, 120, 0.1);
  color: var(--color-primary);
}

.toast-content {
  flex: 1;
  font-size: 14px;
  color: var(--text-primary);
  font-weight: 500;
}



@keyframes spin {
  to { transform: rotate(360deg); }
}

/* 保存按钮加载状态 */
